import os


def check(line):
    pairs = {')': '(', ']': '[', '}': '{'}
    closers = {'(': ')', '[': ']', '{': '}'}
    stack = []
    for i, ch in enumerate(line, 1):
        if ch in closers:
            stack.append(ch)
        elif ch in pairs:
            if not stack:
                return f"col {i}: unexpected {ch}"
            top = stack[-1]
            if top != pairs[ch]:
                return f"col {i}: expected {closers[top]}, found {ch}"
            stack.pop()
    if stack:
        return f"unclosed {closers[stack[-1]]}"
    return "ok"


def main():
