import os
import heapq


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "routes.txt")
    with open(path, "r", encoding="utf-8", errors="surrogateescape") as f:
        lines = f.read().splitlines()

    adj = {}
    trips = []
    for line in lines:
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        p = s.split()
        if p[0] == "road" and len(p) >= 4:
            x, y, c = p[1], p[2], int(p[3])
            adj.setdefault(x, []).append((y, c))
            adj.setdefault(y, []).append((x, c))
        elif p[0] == "trip" and len(p) >= 3:
            trips.append((p[1], p[2]))

    cache = {}

    def dists(target):
        if target in cache:
            return cache[target]
        d = {target: 0}
        pq = [(0, target)]
        while pq:
            du, u = heapq.heappop(pq)
            if du > d.get(u, float("inf")):
                continue
            for v, c in adj.get(u, ()):
                nd = du + c
                if nd < d.get(v, float("inf")):
                    d[v] = nd
                    heapq.heappush(pq, (nd, v))
        cache[target] = d
        return d

    out = []
    for x, y in trips:
        if x == y:
            out.append(f"{x} 0")
            continue
        d = dists(y)
        if x not in d:
            out.append(f"{x} {y} unreachable")
            continue
        path_nodes = [x]
        u = x
        while u != y:
            best = None
            for v, c in adj[u]:
                if v in d and c + d[v] == d[u]:
                    if best is None or v.encode("utf-8", "surrogateescape") < best.encode("utf-8", "surrogateescape"):
                        best = v
            u = best
            path_nodes.append(u)
        out.append(" -> ".join(path_nodes) + f" {d[x]}")

    print("\n".join(out))


