import json
import os


def strip_nulls(v):
    if isinstance(v, dict):
        return {k: strip_nulls(x) for k, x in v.items() if x is not None}
    return v


def merge(base, over):
    result = dict(base)
    for k, v in over.items():
        if v is None:
            result.pop(k, None)
        elif isinstance(v, dict) and isinstance(result.get(k), dict):
            result[k] = merge(result[k], v)
        else:
            result[k] = strip_nulls(v)
    return result


def flatten(v, path, out):
    if isinstance(v, dict):
        if not v and path:
            out.append((path, "{}"))
        for k, x in v.items():
            flatten(x, path + "." + k if path else k, out)
    elif isinstance(v, list):
        if not v and path:
            out.append((path, "[]"))
        for i, x in enumerate(v):
            flatten(x, path + "." + str(i) if path else str(i), out)
    else:
        out.append((path, json.dumps(v, ensure_ascii=False)))


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "base.json"), encoding="utf-8") as f:
        base = json.load(f)
    with open(os.path.join(d, "override.json"), encoding="utf-8") as f:
        over = json.load(f)
    merged = merge(base, over)
    out = []
    flatten(merged, "", out)
    out.sort(key=lambda t: t[0].encode("utf-8"))
    lines = [p + "=" + v for p, v in out]
    if lines:
        print("\n".join(lines))


