import os
import sys


def main():
    src = os.environ["SRC"]
    dst = os.environ["DST"]

    def files(d):
        return sorted(
            n.encode("utf-8", "surrogateescape")
            for n in os.listdir(d)
            if os.path.isfile(os.path.join(d, n))
        )

    src_files = files(src)
    dst_files = set(files(dst))
    out = []
    for nb in src_files:
        name = os.fsdecode(nb)
        sp = os.path.join(src, name)
        dp = os.path.join(dst, name)
        with open(sp, "rb") as f:
            data = f.read()
        if nb in dst_files:
            with open(dp, "rb") as f:
                old = f.read()
            if old == data:
                status = "same"
            else:
                status = "updated"
        else:
            status = "added"
        if status != "same":
            with open(dp, "wb") as f:
                f.write(data)
        out.append((status, name))
    src_set = set(src_files)
    kept = len([n for n in dst_files if n not in src_set])
    w = sys.stdout.buffer
    for status, name in out:
        w.write(status.encode() + b" " + os.fsencode(name) + b"\n")
    w.write(b"kept " + str(kept).encode() + b"\n")
    w.flush()


