import json
import tempfile


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["COUNTS"]

    counts = {}
    if os.path.exists(kv_path):
        try:
            with open(kv_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict):
                counts = {str(k): int(v) for k, v in data.items()}
        except (ValueError, OSError):
            counts = {}

    with open(os.path.join(input_dir, "visits.txt"), "rb") as f:
        raw = f.read()

    for line in raw.split(b"\n"):
        line = line.strip()
        if not line:
            continue
        page = line.decode("utf-8", errors="surrogateescape")
        counts[page] = counts.get(page, 0) + 1

    directory = os.path.dirname(os.path.abspath(kv_path))
    fd, tmp = tempfile.mkstemp(dir=directory, prefix=".kv-")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(counts, f)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, kv_path)
    except BaseException:
        if os.path.exists(tmp):
            os.unlink(tmp)
        raise

    items = sorted(
        counts.items(),
        key=lambda kv: (-kv[1], kv[0].encode("utf-8", errors="surrogateescape")),
    )
    out = sys.stdout.buffer
    for page, total in items:
        out.write(page.encode("utf-8", errors="surrogateescape") + b" " + str(total).encode() + b"\n")
    out.flush()


