    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.read().splitlines()
    except OSError:
        lines = []

    max_w = None
    for line in lines:
        parts = line.split()
        if len(parts) != 2:
            continue
        try:
            ts = int(parts[0])
        except ValueError:
            continue
        client = parts[1]
        w = str(ts // 60)
        if max_w is None or ts // 60 > max_w:
            max_w = ts // 60
        bucket = state.setdefault(w, {})
