import os
import re
import json
import threading
import fcntl
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

KV_PATH = os.environ.get("COUNTS", "counts.json")
LOCK = threading.Lock()
NAME_RE = re.compile(r"[a-z0-9-]{1,32}")


def load():
    try:
        with open(KV_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
            if isinstance(data, dict):
                return data
    except (FileNotFoundError, ValueError, OSError):
        pass
    return {}


def save(data):
    tmp = KV_PATH + ".tmp.%d.%d" % (os.getpid(), threading.get_ident())
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, KV_PATH)


class FileLock:
    def __enter__(self):
        LOCK.acquire()
        self.fd = os.open(KV_PATH + ".lock", os.O_CREAT | os.O_RDWR, 0o644)
        fcntl.flock(self.fd, fcntl.LOCK_EX)
        return self

    def __exit__(self, *a):
        try:
            fcntl.flock(self.fd, fcntl.LOCK_UN)
            os.close(self.fd)
        finally:
            LOCK.release()


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send_json(self, status, obj):
        body = json.dumps(obj).encode("utf-8")
        self.send_response(status)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(body)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def handle_any(self):
        try:
            n = int(self.headers.get("content-length") or 0)
        except ValueError:
            n = 0
        if n > 0:
            self.rfile.read(n)

        method = self.command
        path = self.path
        if "?" in path:
            path = path.split("?", 1)[0]

        if method == "POST" and path.startswith("/hit/"):
            name = path[5:]
            if not NAME_RE.fullmatch(name):
                return self.send_json(400, {"error": "bad name"})
            with FileLock():
                data = load()
                data[name] = int(data.get(name, 0)) + 1
                save(data)
                count = data[name]
            return self.send_json(200, {"name": name, "count": count})

        if method == "GET" and path.startswith("/count/"):
            name = path[7:]
            if not NAME_RE.fullmatch(name):
                return self.send_json(400, {"error": "bad name"})
            with FileLock():
                data = load()
            return self.send_json(200, {"name": name, "count": int(data.get(name, 0))})

        if method == "GET" and path == "/top":
            with FileLock():
                data = load()
            items = sorted(data.items(), key=lambda kv: (-int(kv[1]), kv[0].encode("utf-8")))[:3]
            return self.send_json(200, [{"name": k, "count": int(v)} for k, v in items])

        return self.send_json(404, {"error": "not found"})

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = do_HEAD = do_OPTIONS = handle_any


def main():
    port = int(os.environ.get("PORT", "8000"))
    server = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    server.daemon_threads = True
    server.serve_forever()


if __name__ == "__main__":
    main()

import json
import os
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

STORE = os.environ.get("STORE")
LOCK = threading.Lock()
STATE = {"next_id": 1, "todos": []}


def load():
    try:
        with open(STORE, "r", encoding="utf-8") as f:
            d = json.load(f)
        if isinstance(d, dict) and isinstance(d.get("todos"), list):
            STATE["todos"] = d["todos"]
            STATE["next_id"] = int(d.get("next_id", 1))
            for t in STATE["todos"]:
                if t["id"] >= STATE["next_id"]:
                    STATE["next_id"] = t["id"] + 1
    except Exception:
        pass


def save():
    if not STORE:
        return
    tmp = STORE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(STATE, f)
    os.replace(tmp, STORE)


def parse_id(seg):
    if seg.isascii() and seg.isdigit() and str(int(seg)) == seg:
        return int(seg)
    return None


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj=None):
        body = b"" if obj is None else json.dumps(obj).encode()
        self.send_response(code)
        if obj is not None:
            self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if body:
            self.wfile.write(body)

    def body(self):
        n = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(n) if n > 0 else b""
        try:
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def nf(self):
        self.send(404, {"error": "not found"})

    def handle_any(self):
        method = self.command
        data = self.body() if method in ("POST", "PATCH") else None
        if method not in ("POST", "PATCH"):
            n = int(self.headers.get("Content-Length") or 0)
            if n > 0:
                self.rfile.read(n)
        u = urlsplit(self.path)
        parts = u.path.split("/")
        with LOCK:
            if u.path == "/todos":
                if method == "POST":
                    t = data.get("title") if isinstance(data, dict) else None
                    if not isinstance(t, str) or not t.strip():
                        return self.send(400, {"error": "title required"})
                    todo = {"id": STATE["next_id"], "title": t.strip(), "done": False}
                    STATE["next_id"] += 1
                    STATE["todos"].append(todo)
                    save()
                    return self.send(201, todo)
                if method == "GET":
                    items = STATE["todos"]
                    q = parse_qs(u.query).get("done")
                    if q:
                        if q[-1] == "true":
                            items = [t for t in items if t["done"] is True]
                        elif q[-1] == "false":
                            items = [t for t in items if t["done"] is False]
                    return self.send(200, sorted(items, key=lambda t: t["id"]))
                return self.nf()
            if len(parts) == 3 and parts[0] == "" and parts[1] == "todos":
                tid = parse_id(parts[2])
                todo = None
                if tid is not None:
                    for t in STATE["todos"]:
                        if t["id"] == tid:
                            todo = t
                            break
                if todo is None or method not in ("GET", "PATCH", "DELETE"):
                    return self.nf()
                if method == "GET":
                    return self.send(200, todo)
                if method == "DELETE":
                    STATE["todos"].remove(todo)
                    save()
                    return self.send(204)
                bad = {"error": "bad update"}
                if not isinstance(data, dict):
                    return self.send(400, bad)
                upd = {}
                if "title" in data:
                    t = data["title"]
                    if not isinstance(t, str) or not t.strip():
                        return self.send(400, bad)
                    upd["title"] = t.strip()
                if "done" in data:
                    if not isinstance(data["done"], bool):
                        return self.send(400, bad)
                    upd["done"] = data["done"]
                todo.update(upd)
                save()
                return self.send(200, todo)
            return self.nf()

    do_GET = do_POST = do_PATCH = do_DELETE = do_PUT = do_HEAD = do_OPTIONS = handle_any


if __name__ == "__main__":
    load()
    srv = ThreadingHTTPServer(("127.0.0.1", int(os.environ["PORT"])), H)
    srv.daemon_threads = True
    srv.serve_forever()

