    "CREATE TABLE IF NOT EXISTS notes ("
    "id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, "
    "body TEXT NOT NULL, tags TEXT NOT NULL)"
)
lock = threading.Lock()

