        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(data)

    def nf(self):
        self.send(404, {"error": "not found"})

    def read_body(self):
        try:
            n = int(self.headers.get("content-length") or 0)
        except ValueError:
            n = 0
        return self.rfile.read(n) if n > 0 else b""

    def handle_any(self):
        raw = self.read_body()
        method = self.command
        u = urlsplit(self.path)
        path = u.path
        if method == "POST" and path == "/notes":
            return self.create(raw)
        if method == "GET" and path == "/notes":
            return self.list(u.query)
        m = ID_RE.match(path)
        if m and method in ("GET", "DELETE"):
            nid = int(m.group(1))
            with lock:
                row = conn.execute(
                    "SELECT id,title,body,tags FROM notes WHERE id=?", (nid,)
                ).fetchone()
                if row is None:
                    return self.nf()
                if method == "GET":
                    return self.send(
                        200,
                        {"id": row[0], "title": row[1], "body": row[2],
                         "tags": json.loads(row[3])},
                    )
                conn.execute("DELETE FROM notes WHERE id=?", (nid,))
            return self.send(200, {"deleted": nid})
        return self.nf()

    def create(self, raw):
        bad = lambda: self.send(400, {"error": "invalid note"})
        try:
            d = json.loads(raw.decode("utf-8"))
        except Exception:
            return bad()
        if not isinstance(d, dict):
            return bad()
        title = d.get("title")
        body = d.get("body")
        tags = d.get("tags", [])
        if not isinstance(title, str) or not title:
            return bad()
        if not isinstance(body, str):
            return bad()
        if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
            return bad()
        out = []
        for t in tags:
            t = t.lower()
            if t not in out:
                out.append(t)
        with lock:
            cur = conn.execute(
                "INSERT INTO notes(title,body,tags) VALUES(?,?,?)",
                (title, body, json.dumps(out)),
            )
            nid = cur.lastrowid
        self.send(201, {"id": nid})

    def list(self, query):
        qs = parse_qs(query, keep_blank_values=True)
        tag = qs["tag"][0].lower() if "tag" in qs else None
        q = qs["q"][0] if "q" in qs else None
        with lock:
            rows = conn.execute(
                "SELECT id,title,body,tags FROM notes ORDER BY id DESC"
            ).fetchall()
        res = []
        for i, t, b, tg in rows:
            if tag is not None and tag not in json.loads(tg):
                continue
            if q is not None and q not in t and q not in b:
                continue
            res.append({"id": i, "title": t})
        self.send(200, res)

