import json
import os
import sys
import urllib.request
import urllib.parse


BASE = os.environ["API"].rstrip("/")


def get(path):
    with urllib.request.urlopen(BASE + path, timeout=30) as r:
        if not (200 <= r.status < 300):
            raise RuntimeError("status")
        return json.loads(r.read().decode("utf-8"))


def fmt(v):
    sign = "-" if v < 0 else ""
    q, r = divmod(abs(v), 10)
    return "%s%d.%d" % (sign, q, r)


def summarize(name, sid):
    try:
        data = get("/stations/%s/readings" % urllib.parse.quote(str(sid), safe=""))
        temps = [
            x["temp"]
            for x in data.get("readings", [])
            if isinstance(x.get("temp"), int) and not isinstance(x.get("temp"), bool)
        ]
    except Exception:
        return "%s unavailable" % name
    if not temps:
        return "%s no data" % name
    n = len(temps)
    s = sum(temps)
    avg = abs(s) // n
    if s < 0:
        avg = -avg
    return "%s min=%s max=%s avg=%s n=%d" % (name, fmt(min(temps)), fmt(max(temps)), fmt(avg), n)


def main():
    stations = get("/stations")["stations"]
    stations = sorted(stations, key=lambda s: s["name"].encode("utf-8"))
    out = [summarize(s["name"], s["id"]) for s in stations]
    sys.stdout.buffer.write(("\n".join(out) + ("\n" if out else "")).encode("utf-8"))


main()
